const pick=()=>{try{const q=new URLSearchParams(location.search).get('lang');if(q==='ja'||q==='en'){localStorage.setItem('after-school-lang',q);return q;}const s=localStorage.getItem('after-school-lang');if(s)return s;}catch{}return typeof navigator!=='undefined'&&navigator.language?.startsWith('ja')?'ja':'en';};
export const lang=typeof window==='undefined'?'en':pick();
export const t=s=>lang==='ja'?ja[s]??s:s;
export const tf=(s,...a)=>t(s).replace(/\{(\d)\}/g,(_,i)=>a[i]);
const ATTRS=['aria-label','title','alt','placeholder'];
function swap(node){const v=node.nodeValue,k=v.trim(),j=ja[k];if(j&&j!==k)node.nodeValue=v.replace(k,j);}
export function localize(root=document.body){
 if(lang!=='ja')return;
 const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);while(w.nextNode())swap(w.currentNode);
 for(const el of [root,...root.querySelectorAll('*')])for(const a of ATTRS){const v=el.getAttribute?.(a);if(v&&ja[v])el.setAttribute(a,ja[v]);}
}
// Re-localize anything the app renders later (dialogs, wardrobe, toasts).
if(typeof window!=='undefined'&&lang==='ja'){
 document.documentElement.lang='ja';document.title=t(document.title);
 addEventListener('DOMContentLoaded',()=>{localize();new MutationObserver(ms=>{for(const m of ms){if(m.type==='characterData')swap(m.target);else if(m.type==='attributes'){const v=m.target.getAttribute(m.attributeName);if(v&&ja[v])m.target.setAttribute(m.attributeName,ja[v]);}else for(const n of m.addedNodes)n.nodeType===3?swap(n):n.nodeType===1&&localize(n);}}).observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:ATTRS});});
}
